importedTypeDeclarations.text:
export interface AvatarAnimationClipCatalogEntry {
  actionId: AvatarAnimationActionId;
  clipId: string;
  labelDe: string;
  /** Canonical bones required for this clip to be playable. */
  requiredBones: readonly SagaTreeHumanoidBoneId[];
  /** Preferred rigid attachment anchor while this clip plays. */
  attachmentAnchor: SagaTreeHumanoidAnchorId;
  loop: boolean;
}

export interface AvatarAnimationSupportResult {
  contractVersion: typeof ANIMATION_CONTRACT_VERSION;
  rigContractVersion: typeof RIG_CONTRACT_VERSION;
  /** Actions that may be activated in preview. */
  supported: readonly AvatarAnimationActionId[];
  /** Unsupported action → DE explanation (never a hard error). */
  unsupportedReasons: Readonly<Partial<Record<AvatarAnimationActionId, string>>>;
  defaultAction: AvatarAnimationActionId | null;
}

export interface AssetAuthoringProvenanceV1 {
  license: AssetAuthoringLicenseKind;
  /** Human-readable attribution / source note — required for publish. */
  attributionDe: string;
  /** Optional upstream URL (docs only — never a free mesh download URL in contracts). */
  sourceNote?: string;
}

export interface AssetAuthoringManifestV1 {
  contractVersion: typeof ASSET_AUTHORING_CONTRACT_VERSION;
  generationContractVersion: typeof AVATAR_3D_GENERATION_CONTRACT_VERSION;
  modularGlbContractVersion: typeof MODULAR_AVATAR_GLB_CONTRACT_VERSION;
  assetId: string;
  kind: AssetAuthoringKind;
  /** Semantic version of the published asset (e.g. 1.0.0). */
  assetVersion: string;
  /** Target body family when kind is base-body / wearable fit. */
  bodyFamily?: AvatarV2BodyFamily;
  providerId: Avatar3dGenerationProviderId;
  modelId: string;
  prompt: string;
  /** Logical reference asset keys or allowlisted image keys — never raw secrets. */
  references: readonly string[];
  settings: Avatar3dGenerationSettings;
  provenance: AssetAuthoringProvenanceV1;
  /** Hex or base64url checksum of published bytes. */
  outputChecksum: string;
  styleTags: readonly AssetAuthoringStyleTag[];
  createdAt: string;
}

export interface AssetAuthoringGoldenCriteriaV1 {
  requirePose: PoseMode;
  requireMtoonCompatible: boolean;
  requireAdultStylized: boolean;
  forbidChibi: boolean;
  requireModularExtrasWhenKind: readonly AssetAuthoringKind[];
  minRigHumanoidBonesForBaseBody: number;
}

export interface AssetAuthoringCandidateEvidenceV1 {
  pose: PoseMode | 'unknown';
  modularGlbStatus: ModularAvatarGlbStatus | 'absent';
  humanoidBoneCount: number;
  morphTargetCount: number;
  mtoonMaterialHint: boolean;
  styleTagsClaimed: readonly AssetAuthoringStyleTag[];
  /** Client/provider style claims are never trusted alone. */
  visualReviewNotesDe?: string;
  byteSize: number;
  checksum: string;
}

export interface AssetAuthoringValidationIssue {
  code: string;
  severity: 'blocker' | 'warn';
  messageDe: string;
}

export interface AssetAuthoringValidationResultV1 {
  contractVersion: typeof ASSET_AUTHORING_CONTRACT_VERSION;
  ok: boolean;
  score: number;
  issues: readonly AssetAuthoringValidationIssue[];
}

export interface AssetAuthoringCandidateV1 {
  candidateId: string;
  status: AssetAuthoringCandidateStatus;
  providerId: Avatar3dGenerationProviderId;
  modelId: string;
  settings: Avatar3dGenerationSettings;
  evidence: AssetAuthoringCandidateEvidenceV1;
  validation?: AssetAuthoringValidationResultV1;
}

export interface AvatarArtifactAssetRef {
  assetKey: string;
  /** Path inside private `character-avatars` bucket (`{owner}/{id}.{ext}`). */
  storagePath: string;
  format: AvatarArtifactFormat;
}

export interface AvatarArtifactSourceRef {
  origin: AvatarV2Source;
  /** Legacy wire (`meshy`) when mapping from v1 source. */
  legacySource?: AvatarSource;
  importAssetId?: string;
  generateJobId?: string;
  templateId?: string;
  /** Infrastructure adapter id (meshy, tripo, …) — never a capability proof. */
  providerId?: string;
}

export interface AvatarArtifactV2 {
  contractVersion: typeof AVATAR_ARTIFACT_CONTRACT_VERSION;
  artifactId: string;
  ownerUserId: string;
  characterId: string | null;
  source: AvatarArtifactSourceRef;
  asset: AvatarArtifactAssetRef;
  analysisStatus: AvatarArtifactAnalysisStatus;
  materializationStatus: AvatarArtifactMaterializationStatus;
  isActive: boolean;
  /** Monotonic domain schema; DB column mirrors this. */
  schemaVersion: 2;
  /** Optional client/provider retry key — unique per owner when set. */
  idempotencyKey?: string;
  createdAt: string;
  updatedAt: string;
}

export interface AvatarArtifactMaterializeInput {
  artifactId: string;
  ownerUserId: string;
  characterId?: string | null;
  origin: AvatarV2Source;
  legacySource?: AvatarSource;
  format: AvatarArtifactFormat;
  storagePath: string;
  importAssetId?: string;
  generateJobId?: string;
  templateId?: string;
  providerId?: string;
  idempotencyKey?: string;
  /** Wall-clock ISO; tests may inject. */
  nowIso?: string;
}

export type AvatarArtifactActivateResult =
  | { ok: true; artifact: AvatarArtifactV2 }
  | { ok: false; reasonDe: string };

export interface AvatarArtifactRepository {
  create(artifact: AvatarArtifactV2): Promise<AvatarArtifactV2>;
  getById(ownerUserId: string, artifactId: string): Promise<AvatarArtifactV2 | null>;
  listByOwner(ownerUserId: string, characterId?: string | null): Promise<readonly AvatarArtifactV2[]>;
  activate(ownerUserId: string, artifactId: string): Promise<AvatarArtifactActivateResult>;
  findByIdempotencyKey(
    ownerUserId: string,
    idempotencyKey: string,
  ): Promise<AvatarArtifactV2 | null>;
}

export interface AvatarImportArtifact {
  artifactId: string;
  format: AvatarImportFormat;
  byteSize: number;
  storagePath: string;
  /** Signed or app-relative URL for AvatarCanvas — not a free remote mesh URL from the user. */
  modelUrl: string;
  /** Always starts as pending after import; #6 owns upgrades. */
  rigAnalysisStatus: AvatarRigAnalysisStatus;
}

export interface AvatarImportEarlyCheck {
  ok: boolean;
  format?: AvatarImportFormat;
  message?: string;
}

export interface AvatarSaveExportPayloadV1 {
  contractVersion: typeof AVATAR_SAVE_EXPORT_VERSION;
  morphContractVersion: typeof MORPH_CONTRACT_VERSION;
  rigContractVersion: typeof RIG_CONTRACT_VERSION;
  mtoonProfileVersion: typeof MTOON_PROFILE_VERSION;
  baseBodyContractVersion: typeof BASE_BODY_CONTRACT_VERSION;
  baseBodyAssetVersion: string;
  preset: string;
  modelFormat: 'vrm' | 'glb';
  /** Allowlisted catalog path when no imported mesh was copied into the package. */
  catalogBasePath?: string;
  /** True when source mesh bytes were embedded; false for metadata-only package. */
  embedsSourceMesh: boolean;
  baseTraits: BaseTraitSelection;
  morph: SagaTreeAvatarMorphStateV1;
  /** Explicitly empty — overlays are filtered out and must stay empty. */
  runtimeOverlays: readonly [];
}

export interface AvatarSaveExportArtifact {
  artifactId: string;
  storagePath: string;
  modelUrl: string;
  byteSize: number;
  format: 'glb';
  payload: AvatarSaveExportPayloadV1;
}

export interface AvatarSourceOptionMeta {
  source: AvatarSource;
  titleDe: string;
  expectationDe: 'voll editierbar' | 'Import' | 'KI-generiert';
  summaryDe: string;
}

export interface AvatarSourceSwitchDecision {
  needsConfirm: boolean;
  messageDe?: string;
}

export interface AvatarStructureNodeEvidence {
  name?: string;
  extras?: unknown;
  meshIndex?: number;
  skinIndex?: number;
}

export interface AvatarStructureMeshEvidence {
  name?: string;
  primitiveCount: number;
  morphTargetCount: number;
  isSkinned: boolean;
}

export interface AvatarStructureEvidence {
  /** Byte size of the scanned asset (0 when fixture-only). */
  byteSize: number;
  nodeCount: number;
  meshCount: number;
  skinnedMeshCount: number;
  skeletonCount: number;
  boneCount: number;
  morphTargetCount: number;
  /** Canonical humanoid bones detected (source names optional). */
  humanoidBones: Readonly<Partial<Record<SagaTreeHumanoidBoneId, string>>>;
  nodes: readonly AvatarStructureNodeEvidence[];
  meshes: readonly AvatarStructureMeshEvidence[];
  /** True when scanner hit a bound and stopped early. */
  truncated: boolean;
  /** Scanner rejected remote URI / bufferView URI resolution. */
  rejectedRemoteUri: boolean;
  /** Parse/IO failure. */
  parseError?: string;
}

export interface AvatarStructureRoleHit {
  role: ModularAvatarGlbNodeRole;
  nodeName?: string;
  fromMetadata: boolean;
}

export interface AvatarStructureAnalysisResultV2 {
  contractVersion: typeof AVATAR_STRUCTURE_ANALYZER_CONTRACT_VERSION;
  status: AvatarStructureAnalysisStatus;
  anatomy: AvatarV2Anatomy;
  /** Analyzer kind: full | partial | baked */
  modularityKind: AvatarStructureModularityKind;
  /** Mapped onto Avatar V2 composition modularity axis. */
  modularity: AvatarV2Modularity;
  roles: readonly AvatarStructureRoleHit[];
  humanoidBoneCount: number;
  missingHumanoidBones: readonly SagaTreeHumanoidBoneId[];
  limitations: readonly string[];
  warnings: readonly string[];
  evidence: {
    nodeCount: number;
    meshCount: number;
    skinnedMeshCount: number;
    skeletonCount: number;
    boneCount: number;
    morphTargetCount: number;
    truncated: boolean;
    metadataValidated: boolean;
    metadataContradictedGeometry: boolean;
  };
  /** Client preview must set false; server persist sets true. */
  authoritative: boolean;
}

export interface BaseBodyMorphTargetMap {
  /** Morph contract key → authored blendshape / morph target name on the mesh. */
  body: Readonly<Record<AvatarMorphBodyKey, string>>;
  face: Readonly<Record<AvatarMorphFaceKey, string>>;
}

export interface BaseBodyFitRange {
  traitSocket: BaseBodyTraitSocket;
  /** Normalized morph axes that affect this socket's scale fit. */
  drivenBy: readonly AvatarMorphParamKey[];
  minScale: number;
  maxScale: number;
}

export interface BaseBodyProvenance {
  licenseSpdx: 'CC0-1.0' | 'LicenseRef-SagaTree-Internal';
  licenseUrl: string;
  source: string;
  notes: string;
}

export interface SagaTreeBaseBodyManifestV1 {
  contractVersion: typeof BASE_BODY_CONTRACT_VERSION;
  /** Version string — legacy `sagatree-base-humanoid-v1.0.0` or family `sd_body_*_v1.0.0`. */
  assetVersion: string;
  rigVersion: typeof RIG_CONTRACT_VERSION;
  morphContractVersion: typeof MORPH_CONTRACT_VERSION;
  /** Legacy `sagatree-base-humanoid-v1` or canonical `sd_body_{standard|compact|heavy}_v1`. */
  assetId: string;
  displayNameDe: string;
  /** Allowlisted self-hosted relative path (no remote arbitrary URLs). */
  selfHostedPath: string;
  format: 'vrm' | 'glb';
  morphTargets: BaseBodyMorphTargetMap;
  materialSlots: readonly BaseBodyMaterialSlot[];
  traitSockets: readonly BaseBodyTraitSocket[];
  fitRanges: readonly BaseBodyFitRange[];
  provenance: BaseBodyProvenance;
}

export interface BaseBodySpeciesPresetV1 {
  id: BaseBodySpeciesId;
  labelDe: string;
  /** Overlay morph/colors/traits applied onto defaults (deterministic). */
  morphOverlay: Partial<{
    body: Partial<Record<AvatarMorphBodyKey, number>>;
    face: Partial<Record<AvatarMorphFaceKey, number>>;
    colors: Partial<AvatarMorphColorsV1>;
    traits: Partial<{
      markings: readonly string[];
      scars: readonly string[];
      cybernetics: readonly string[];
    }>;
  }>;
  /** Base trait catalog IDs (group → option). */
  traits: Readonly<{
    head: string;
    ears: string;
    hair: string;
    clothing: string;
    accessory: string;
  }>;
  legacyPresetId: string;
}

export interface BaseBodyMorphCapabilityReport {
  flags: readonly AvatarMorphCapabilityFlag[];
  missingBodyTargets: readonly AvatarMorphBodyKey[];
  missingFaceTargets: readonly AvatarMorphFaceKey[];
  limitations: readonly string[];
}

export interface BaseBodyMorphFixtureCase {
  id: string;
  labelDe: string;
  morph: SagaTreeAvatarMorphStateV1;
}

export interface BodyConversionFamilyOptionV1 {
  familyId: BodyConversionTargetFamily;
  labelDe: string;
  recommended: boolean;
  previewHintDe: string;
}

export interface BodyConversionRequestV1 {
  sourceArtifactId: string;
  sourceImportAssetId: string;
  sourceModelUrl: string;
  anatomy: AvatarV2Anatomy;
  modularity: AvatarV2Modularity;
  recommendedFamily: AvatarV2BodyFamily;
  /** Player-selected target; must be allowlisted. */
  targetFamily: BodyConversionTargetFamily;
  /** Optional identity fidelity estimate 0..1 from analysis heuristics. */
  identityFidelityEstimate?: number;
}

export interface BodyConversionResultV1 {
  contractVersion: typeof BODY_CONVERSION_FLOW_CONTRACT_VERSION;
  status: BodyConversionStatus;
  targetFamily: BodyConversionTargetFamily;
  approachIds: readonly IdentityTransferApproachId[];
  morphState: SagaTreeAvatarMorphStateV1;
  anatomy: 'humanoid';
  modularity: 'modular-parts';
  bodyCompatibility: BodyConversionTargetFamily;
  traits: {
    head: string;
    ears: string;
    hair: string;
    clothing: string;
    accessory: string;
  };
  colors: { hair: string; skin: string };
  tradeoffCopyDe: string;
  limitationsDe: readonly string[];
  /** Converted path uses catalog body — never the source mesh URL. */
  usesCanonicalBody: true;
  /** Source ids preserved for undo / re-activate original. */
  sourceArtifactId: string;
  sourceImportAssetId: string;
  sourceModelUrl: string;
}

export interface BodyFamilyVariantResolveInput {
  wearableId: string;
  bodyFamily: string;
  morph?: SagaTreeAvatarMorphStateV1;
}

export interface BodyFamilyVariantResolveResult {
  contractVersion: typeof BODY_FAMILY_VARIANT_RESOLVER_VERSION;
  status: BodyFamilyVariantResolveStatus;
  messageDe: string | null;
  wearableId: StarterWearableId | null;
  bodyFamily: CanonicalBodyFamilyId | null;
  assetPath: string | null;
  assetVersion: string | null;
  fitStatus: AvatarFitStatus | null;
  /** Pass-through for hide/mask from wardrobe when resolved. */
  hideRegions: readonly string[];
  bodyMaskRegions: readonly string[];
}

export interface BodyProfileProportionsV1 {
  /** (shoulder width) / height */
  shoulderToHeight: number;
  /** (hip width) / height */
  hipToHeight: number;
  /** (torso length hips→neck) / height */
  torsoToHeight: number;
  /** (leg length hips→foot) / height */
  legToHeight: number;
  /** (arm span proxy) / height */
  armToHeight: number;
  /** head height / overall height */
  headToHeight: number;
}

export interface BodyProfileV1 {
  contractVersion: typeof BODY_PROFILE_CONTRACT_VERSION;
  proportions: BodyProfileProportionsV1;
  /** Measurement unit before normalization (informational). */
  sourceUnit: 'meter';
  /** Scale applied so height ≈ 1.0 before ratios. */
  normalizeScale: number;
  validationStatus: BodyProfileValidationStatus;
  limitations: readonly string[];
}

export interface BodyFamilyReferenceProfileV1 {
  familyId: BodyProfileFamilyId;
  labelDe: string;
  proportions: BodyProfileProportionsV1;
}

export interface FamilyScoreV1 {
  familyId: BodyProfileFamilyId;
  /** 0..1 similarity (1 = identical proportions). */
  score: number;
}

export interface FamilyCompatibilityResultV1 {
  contractVersion: typeof BODY_PROFILE_CONTRACT_VERSION;
  status: FamilyCompatibilityStatus;
  /** Winning clothing family when status=family-compatible; else custom. */
  recommendedFamily: AvatarV2BodyFamily;
  scores: readonly FamilyScoreV1[];
  /** Minimum score required for family-compatible. */
  threshold: number;
  confidence: number;
  validationStatus: BodyProfileValidationStatus;
  limitations: readonly string[];
}

export interface HumanoidMetricLengthsV1 {
  height: number;
  shoulderWidth: number;
  hipWidth: number;
  torsoLength: number;
  legLength: number;
  armLength: number;
  headHeight: number;
}

export interface BodyRegionMaskSnapshot {
  contractVersion: typeof BODY_REGION_MASK_CONTRACT_VERSION;
  /** Region → active overlay count. */
  counts: Readonly<Partial<Record<EquipmentHideRegion, number>>>;
}

export interface BodyRegionMaskDelta {
  /** Regions whose visibility should become hidden (count 0→1). */
  newlyHidden: readonly EquipmentHideRegion[];
  /** Regions whose visibility should become visible (count 1→0). */
  newlyRestored: readonly EquipmentHideRegion[];
}

export interface CanonicalBodyFamilyManifestV1 {
  contractVersion: typeof CANONICAL_BODY_FAMILIES_CONTRACT_VERSION;
  baseBodyContractVersion: typeof BASE_BODY_CONTRACT_VERSION;
  authoringContractVersion: typeof ASSET_AUTHORING_CONTRACT_VERSION;
  familyId: CanonicalBodyFamilyId;
  /** Maps onto Avatar V2 bodyFamily axis. */
  bodyFamily: Extract<AvatarV2BodyFamily, 'standard' | 'compact' | 'heavy'>;
  assetId: CanonicalBodyAssetId;
  assetVersion: string;
  displayNameDe: string;
  selfHostedPath: string;
  format: 'vrm' | 'glb';
  /** Baked everyday clothing is forbidden; underwear is a separate neutral layer. */
  underwearPolicy: 'separate-neutral';
  bakedClothingForbidden: true;
  bodyRegions: readonly CanonicalBodyRegion[];
  materialSlots: readonly BaseBodyMaterialSlot[];
  traitSockets: readonly BaseBodyTraitSocket[];
  morphTargetCount: number;
  provenance: BaseBodyProvenance;
  authoringProvenance: AssetAuthoringProvenanceV1;
  goldenVisualRef: string;
}

export interface CanonicalBodyPublishGateResult {
  ok: boolean;
  issues: readonly string[];
}

export interface AvatarV2Composition {
  contractVersion: typeof AVATAR_V2_COMPOSITION_CONTRACT_VERSION;
  source: AvatarV2Source;
  /** Legacy wire value when present (`meshy` kept for audit/readback). */
  legacySource?: AvatarSource;
  anatomy: AvatarV2Anatomy;
  bodyCompatibility: AvatarV2BodyCompatibility;
  bodyFamily: AvatarV2BodyFamily;
  /** Species / preset identity — orthogonal to bodyFamily. */
  species: string;
  modularity: AvatarV2Modularity;
  /** Only from validated analysis — empty until Analyzer/Rig supplies evidence. */
  capabilities: readonly AvatarRigCapabilityFlag[];
}

export interface ContentPackLicense {
  spdx: string;
  attribution: string;
  provenance: string;
}

export interface ContentPackAssetV1 {
  id: string;
  groupId: AvatarTraitGroupId;
  category: ContentPackCategory;
  label: string;
  tags: readonly string[];
  setting: ContentPackSetting;
  rigVersion: typeof RIG_CONTRACT_VERSION;
  morphContractVersion: typeof MORPH_CONTRACT_VERSION;
  fitRange: AvatarFitRangeV1;
  materialProfile: typeof MTOON_PROFILE_VERSION;
  license: ContentPackLicense;
  /** Deterministic local swatch seed — no remote marketing thumbnails. */
  thumbnailSeed: string;
}

export interface CustomCreatureFlowGuidanceV1 {
  contractVersion: typeof CUSTOM_CREATURE_FLOW_CONTRACT_VERSION;
  recommendOriginal: true;
  headlineDe: string;
  detailDe: string;
  wardrobeLimitationDe: string;
  autoRigOptionalDe: string;
  conversionInterpretationDe: string;
  /** Never force SagaTree morph edit-norm on custom mesh. */
  allowHumanoidMorph: false;
  /** Prefer import-existing per #265 benchmark. */
  preferredRigPath: 'import-existing-rig';
  autoRigOptional: true;
}

export interface CustomCreatureEditorSeedV1 {
  contractVersion: typeof CUSTOM_CREATURE_FLOW_CONTRACT_VERSION;
  modelUrl: string;
  artifactId: string;
  importAssetId: string;
  anatomy: 'custom-creature';
  bodyFamily: 'custom';
  bodyCompatibility: 'custom';
  modularity: ImportOriginalKeepSeedV1['modularity'];
  /** Empty until Analyzer V2 — never invent. */
  capabilities: readonly AvatarRigCapabilityFlagV2[];
  allowHumanoidMorph: false;
  guidance: CustomCreatureFlowGuidanceV1;
}

export type CustomRigBenchmarkScoreRow = Readonly<
  Record<CustomRigBenchmarkScoreAxis, number>
>;

export interface CustomRigBenchmarkCellV1 {
  pathId: CustomRigBenchmarkPathId;
  fixtureId: CustomRigBenchmarkFixtureId;
  profileKind: AvatarRigProfileKindV2;
  scores: CustomRigBenchmarkScoreRow;
  aggregate: number;
  /** Product outcome if this path were chosen alone. */
  outcome: 'viable' | 'limited' | 'unavailable' | 'unsuitable';
  notesDe: string;
}

export interface CustomRigProfileStrategyV1 {
  profileKind: AvatarRigProfileKindV2;
  defaultPathId: CustomRigBenchmarkPathId;
  fallbackPathIds: readonly CustomRigBenchmarkPathId[];
  /** Auto-rig may stay optional when quality is insufficient. */
  autoRigOptional: boolean;
  rationaleDe: string;
}

export interface CustomRigBenchmarkDecisionV1 {
  contractVersion: typeof CUSTOM_RIG_BENCHMARK_CONTRACT_VERSION;
  strategies: readonly CustomRigProfileStrategyV1[];
  /** Paths that must never set capabilities from provider success alone. */
  capabilitiesAlwaysPending: true;
  /** SkinTokens self-host worker status for this spike. */
  skintokensWorkerStatus: 'unavailable' | 'optional-adapter';
  skintokensWorkerNotesDe: string;
}

export interface AvatarMorphEvidenceInput {
  hasBodyMorphTargets: boolean;
  hasFaceMorphTargets: boolean;
}

export interface AvatarMorphEvidenceResolution {
  status: 'pending' | 'ready';
  morphFlags: readonly AvatarMorphCapabilityFlag[];
  limitations: readonly string[];
}

export interface AvatarEditorSurfaces {
  contractVersion: typeof AVATAR_EDITOR_SURFACE_RESOLVER_VERSION;
  status: AvatarEditorCapabilityStatus;
  surfaces: AvatarEditorSurfaceMap;
  morphFlags: readonly AvatarMorphCapabilityFlag[];
  /** End-user DE summary — no internal ticket/contract shorthand. */
  summaryDe: string;
  limitations: readonly string[];
}

export interface AvatarEquipmentLocalTransform {
  position: readonly [number, number, number];
  rotationEuler: readonly [number, number, number];
  scale: readonly [number, number, number];
}

export interface AvatarEquipmentBinding {
  bindingId: string;
  /** Logical model3d:… key — never a raw free URL. */
  assetKey: string;
  assetVersion: string;
  definitionId: string;
  scope: 'core' | 'world' | 'personal';
  ownerUserId?: string;
  worldProfileId?: string | null;
  attachment: EquipmentAttachmentKind;
  anchor: SagaTreeHumanoidAnchorId;
  rigVersion: typeof RIG_CONTRACT_VERSION;
  morphContractVersion: typeof MORPH_CONTRACT_VERSION;
  fitRangeContractVersion: typeof FIT_RANGE_CONTRACT_VERSION;
  /** Optional fit window for this wearable. */
  fitRange?: AvatarFitRangeV1;
  transform: AvatarEquipmentLocalTransform;
  hideRegions: readonly EquipmentHideRegion[];
  /** When set, replaces another trait/socket visual instead of stacking. */
  replaceSocket?: string;
  readOnly?: boolean;
}

export interface AvatarEquipmentVisual {
  instanceId: string;
  definitionId: string;
  bindingId: string | null;
  assetKey: string | null;
  attachment: EquipmentAttachmentKind | null;
  anchor: SagaTreeHumanoidAnchorId | null;
  slots: readonly EquipmentSlot[];
  primarySlot: EquipmentSlot;
  transform: AvatarEquipmentLocalTransform | null;
  hideRegions: readonly EquipmentHideRegion[];
  replaceSocket?: string;
  status: EquipmentVisualStatus;
  fitStatus?: AvatarFitStatus;
  reasonDe: string;
}

export interface AvatarEquipmentVisualProjection {
  contractVersion: typeof EQUIPMENT_VISUAL_CONTRACT_VERSION;
  visuals: readonly AvatarEquipmentVisual[];
}

export interface AvatarEquipmentBindingRepository {
  getBindingForDefinition(definitionId: string): AvatarEquipmentBinding | null;
  listBindings(): readonly AvatarEquipmentBinding[];
}

export interface FaceAnchorAgentReviewAnchorFindingV1 {
  readonly anchorId: SagaTreeFaceAnchorId;
  readonly visualStatus: FaceAnchorVisualStatus;
  readonly anatomyStatus: FaceAnchorVisualStatus;
  readonly sideStatus: FaceAnchorVisualStatus;
  readonly surfaceStatus: FaceAnchorVisualStatus;
  readonly evidenceViews: readonly FaceAnchorAgentReviewEvidenceView[];
  readonly conciseReason: string;
  readonly needsHuman: boolean;
}

export interface FaceAnchorAgentReviewPassReportV1 {
  readonly protocolVersion: typeof FACE_ANCHOR_AGENT_REVIEW_PROTOCOL_VERSION;
  readonly passIndex: 1 | 2 | 3 | 4 | 5;
  /** Opaque reviewer slot id (e.g. agent-pass-3). No chain-of-thought. */
  readonly reviewerId: string;
  readonly evidenceManifestSha256: string;
  readonly modelSha256: string;
  readonly anchorsSha256: string;
  readonly topologyFingerprint: string;
  readonly findings: readonly FaceAnchorAgentReviewAnchorFindingV1[];
  readonly reviewedAt: string;
}

export interface FaceAnchorAgentReviewEvidenceShotV1 {
  readonly view: FaceAnchorAgentReviewEvidenceView;
  readonly relativePath: string;
  readonly sha256: string;
  readonly width: number;
  readonly height: number;
}

export interface FaceAnchorAgentReviewEvidenceManifestV1 {
  readonly protocolVersion: typeof FACE_ANCHOR_AGENT_REVIEW_PROTOCOL_VERSION;
  readonly candidateModelPath: string;
  readonly modelSha256: string;
  readonly topologyFingerprint: string;
  readonly anchorsSha256: string;
  readonly neutralPoseId: 'controlled-neutral-v1';
  readonly liveActEnabled: false;
  readonly animationEnabled: false;
  readonly shots: readonly FaceAnchorAgentReviewEvidenceShotV1[];
  readonly createdAt: string;
}

export interface FaceAnchorAgentReviewDeterministicGateV1 {
  readonly pass: boolean;
  readonly anchorCount: number;
  readonly requiredAnchorCount: 21;
  readonly violations: readonly string[];
}

export interface FaceAnchorAgentReviewDeterministicGateInputV1 {
  readonly anchorCount: number;
  readonly anchorsStructurallyValid: boolean;
  readonly barycentricAllValid: boolean;
  readonly primitiveNodeAllValid: boolean;
