function findBoneObject(
  root: THREE.Object3D,
  sourceName: string | undefined,
): THREE.Object3D | undefined {
  if (!sourceName) return undefined;
  let found: THREE.Object3D | undefined;
  root.traverse((object) => {
    if (found) return;
    if (object.name === sourceName) found = object;
  });
  return found;
}

