applyCameraFrame(frame: AvatarCameraFrameId): void {
    if (this.disposed || !this.currentRoot) return;
    if (frame === 'face' || frame === 'feet' || frame === 'portrait') {
      this.setInspectMode(true);
    }
    if (frame === 'full') {
      this.fitCamera();
      return;
    }
    if (frame === 'portrait') {
      this.fitPortraitCamera();
