function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isDevelopmentKind(value: unknown): value is CharacterAdventureDevelopmentKind {
  return value === 'level' || value === 'species-trait' || value === 'skill' || value === 'note';
}

function isArcStatus(value: unknown): value is CharacterAdventureArcStatus {
  return value === 'active' || value === 'completed' || value === 'left';
}

function normalizeDevelopments(value: unknown): CharacterAdventureDevelopmentDto[] {
  if (!Array.isArray(value)) return [];
  const entries: CharacterAdventureDevelopmentDto[] = [];
  for (const item of value) {
    if (!isRecord(item)) continue;
    if (typeof item.id !== 'string' || typeof item.at !== 'string' || typeof item.title !== 'string') continue;
    if (!isDevelopmentKind(item.kind)) continue;
    const entry: CharacterAdventureDevelopmentDto = {
      id: item.id,
      at: item.at,
      kind: item.kind,
      title: item.title.trim(),
    };
    if (typeof item.detail === 'string' && item.detail.trim()) entry.detail = item.detail.trim();
    if (isRecord(item.meta)) entry.meta = item.meta;
    if (entry.title) entries.push(entry);
  }
  return entries;
}

function mapArc(
  dto: CharacterAdventureArcDto,
  projectName: string,
  projectStatus: string | null,
  sessionCount: number,
): CharacterAdventureArcVm {
  return {
    id: dto.id,
    characterId: dto.character_id,
    projectId: dto.project_id,
    projectName,
    projectStatus,
    sessionCount,
    status: isArcStatus(dto.status) ? dto.status : 'active',
    startedAt: dto.started_at,
    endedAt: dto.ended_at,
    summary: typeof dto.summary === 'string' ? dto.summary : '',
    developments: normalizeDevelopments(dto.developments),
    createdAt: dto.created_at,
    updatedAt: dto.updated_at,
  };
}

function createDevelopmentId(): string {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  return `dev-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
}

async listArcsForCharacter(characterId: string): Promise<CharacterAdventureArcVm[]> {
    const trimmedId = characterId.trim();
    if (!trimmedId) throw new Error('Character id is required.');

    const { data: memberships, error: membershipError } = await supabase
      .from('project_members')
      .select('project_id, joined_at, status')
      .eq('character_id', trimmedId);

    if (membershipError) {
      throw new Error(`Abenteuer-Mitgliedschaften konnten nicht geladen werden: ${membershipError.message}`);
    }

    const activeMemberships = (memberships ?? []).filter((row) => row.status === 'active');

    const { data: existingArcs, error: arcsError } = await supabase
      .from(TABLE)
      .select('*')
      .eq('character_id', trimmedId)
      .order('started_at', { ascending: false });

    if (arcsError) {
      throw new Error(`Abenteuer-Statistik konnte nicht geladen werden: ${arcsError.message}`);
    }

    const arcsByProject = new Map(
      ((existingArcs ?? []) as CharacterAdventureArcDto[]).map((arc) => [arc.project_id, arc]),
    );

    for (const membership of activeMemberships) {
      const projectId = membership.project_id as string;
      if (arcsByProject.has(projectId)) continue;

      const { data: inserted, error: insertError } = await supabase
        .from(TABLE)
        .insert({
          character_id: trimmedId,
          project_id: projectId,
          status: 'active',
          started_at: membership.joined_at ?? new Date().toISOString(),
          developments: [],
        })
        .select('*')
        .single();

      if (insertError) {
        // Concurrent upsert / unique race: reload later in this pass.
        if (insertError.code === '23505') continue;
        throw new Error(`Abenteuer-Bogen konnte nicht angelegt werden: ${insertError.message}`);
      }

      arcsByProject.set(projectId, inserted as CharacterAdventureArcDto);
    }

    const { data: refreshed, error: refreshError } = await supabase
      .from(TABLE)
      .select('*')
      .eq('character_id', trimmedId)
      .order('started_at', { ascending: false });

    if (refreshError) {
      throw new Error(`Abenteuer-Statistik konnte nicht aktualisiert werden: ${refreshError.message}`);
    }

    const arcs = (refreshed ?? []) as CharacterAdventureArcDto[];
    if (arcs.length === 0) return [];

    const projectIds = [...new Set(arcs.map((arc) => arc.project_id))];

    const [{ data: projects, error: projectsError }, { data: sessions, error: sessionsError }] = await Promise.all([
      supabase.from('projects').select('id, name, status').in('id', projectIds),
      supabase.from('sessions').select('project_id').in('project_id', projectIds),
    ]);

    if (projectsError) {
      throw new Error(`Projekte zur Statistik konnten nicht geladen werden: ${projectsError.message}`);
    }
    if (sessionsError) {
      throw new Error(`Sessions zur Statistik konnten nicht geladen werden: ${sessionsError.message}`);
    }

    const projectMeta = new Map(
      (projects ?? []).map((project) => [
        project.id as string,
        {
          name: typeof project.name === 'string' ? project.name : 'Unbenanntes Abenteuer',
          status: typeof project.status === 'string' ? project.status : null,
        },
      ]),
    );

    const sessionCounts = new Map<string, number>();
    for (const session of sessions ?? []) {
      const projectId = session.project_id as string;
      sessionCounts.set(projectId, (sessionCounts.get(projectId) ?? 0) + 1);
    }

    return arcs.map((arc) => {
      const meta = projectMeta.get(arc.project_id);
      return mapArc(
        arc,
        meta?.name ?? 'Unbekanntes Abenteuer',
        meta?.status ?? null,
        sessionCounts.get(arc.project_id) ?? 0,
      );
    });
  }

(project) => [
        project.id as string,
        {
          name: typeof project.name === 'string' ? project.name : 'Unbenanntes Abenteuer',
          status: typeof project.status === 'string' ? project.status : null,
        },
      ]

(arc) => {
      const meta = projectMeta.get(arc.project_id);
      return mapArc(
        arc,
        meta?.name ?? 'Unbekanntes Abenteuer',
        meta?.status ?? null,
        sessionCounts.get(arc.project_id) ?? 0,
      );
    }

async appendDevelopment(
    arcId: string,
    input: AppendAdventureDevelopmentInput,
  ): Promise<CharacterAdventureArcVm> {
    const title = input.title.trim();
    if (!title) throw new Error('Titel der Entwicklung ist erforderlich.');
    if (!isDevelopmentKind(input.kind)) throw new Error('Ungültige Entwicklungsart.');

    const { data: current, error: loadError } = await supabase
      .from(TABLE)
      .select('*')
      .eq('id', arcId)
      .single();

    if (loadError || !current) {
      throw new Error(`Abenteuer-Bogen nicht gefunden: ${loadError?.message ?? 'missing'}`);
    }

    const dto = current as CharacterAdventureArcDto;
    const developments = normalizeDevelopments(dto.developments);
    const nextEntry: CharacterAdventureDevelopmentDto = {
      id: createDevelopmentId(),
      at: new Date().toISOString(),
      kind: input.kind,
      title,
    };
    const detail = input.detail?.trim();
    if (detail) nextEntry.detail = detail;
    if (input.meta && Object.keys(input.meta).length > 0) nextEntry.meta = input.meta;

    const nextDevelopments = [...developments, nextEntry];

    const { data: updated, error: updateError } = await supabase
      .from(TABLE)
      .update({ developments: nextDevelopments })
      .eq('id', arcId)
      .select('*')
      .single();

    if (updateError || !updated) {
      throw new Error(`Entwicklung konnte nicht gespeichert werden: ${updateError?.message ?? 'missing'}`);
    }

    const { data: project } = await supabase
      .from('projects')
      .select('name, status')
      .eq('id', (updated as CharacterAdventureArcDto).project_id)
      .maybeSingle();

    const { count } = await supabase
      .from('sessions')
      .select('id', { count: 'exact', head: true })
      .eq('project_id', (updated as CharacterAdventureArcDto).project_id);

    return mapArc(
      updated as CharacterAdventureArcDto,
      typeof project?.name === 'string' ? project.name : 'Unbenanntes Abenteuer',
      typeof project?.status === 'string' ? project.status : null,
      count ?? 0,
    );
  }

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

function parseFunctionResponse(value: unknown): CharacterLoreFunctionResponse {
  if (!isRecord(value) || typeof value.status !== 'string') {
    return { status: 'error', message: 'Die KI-Antwort hatte ein ungültiges Format.' };
  }

  if (
    value.status === 'ok' &&
    typeof value.story === 'string' &&
    (value.provider === 'openai-compatible' || value.provider === 'ollama') &&
    typeof value.model === 'string'
  ) {
    return {
      status: 'ok',
      story: value.story,
      provider: value.provider,
      model: value.model,
    };
  }

  if (
    (value.status === 'not-configured' || value.status === 'error') &&
    typeof value.message === 'string'
  ) {
    return { status: value.status, message: value.message };
  }

  return { status: 'error', message: 'Die KI-Antwort hatte ein ungültiges Format.' };
}

function hasResponseContext(error: unknown): error is { context: Response } {
  return isRecord(error) && error.context instanceof Response;
}

async function getFunctionErrorMessage(error: unknown): Promise<string | undefined> {
  if (!hasResponseContext(error)) return undefined;

  try {
    const responseBody: unknown = await error.context.clone().json();
    const parsed = parseFunctionResponse(responseBody);
    return parsed.status === 'ok' ? undefined : parsed.message;
  } catch {
    return undefined;
  }
}

async generateBackground(
    request: CharacterLoreGenerationRequest,
  ): Promise<CharacterLoreGenerationResult> {
    const { data, error } = await supabase.functions.invoke('character-lore', {
      body: {
        action: 'generate-background',
        context: request.context,
        currentBackgroundStory: request.currentBackgroundStory,
      },
    });

    if (error) {
      const serverMessage = await getFunctionErrorMessage(error);
      throw new Error(
        serverMessage ??
          'Hintergrundgeschichte konnte nicht generiert werden. Bitte versuche es erneut.',
      );
    }

    const response = parseFunctionResponse(data);
    if (response.status !== 'ok') {
      throw new Error(response.message);
    }

    return {
      story: response.story,
      provider: response.provider,
      model: response.model,
    };
  }

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isPresetOrigin(value: unknown): value is CharacterPresetOrigin {
  return value === 'user' || value === 'system';
}

function isGenderReading(value: unknown): value is CharacterGenderReading {
  return value === 'masculine-read' || value === 'feminine-read' || value === 'diverse';
}

function normalizeSkills(value: unknown): Record<SagaTreeSkillKey, number> {
  const result = createEmptySagaTreeSkillRanks();
  if (!isRecord(value)) return result;
  for (const skill of sagaTreeSkillDefinitions) {
    const rank = value[skill.key];
    if (typeof rank === 'number' && Number.isFinite(rank)) {
      result[skill.key] = Math.max(0, Math.min(5, Math.round(rank)));
    }
  }
  return result;
}

export function assertValidSnapshot(snapshot: CharacterPresetSnapshot): void {
  if (snapshot.schemaVersion !== 1) {
    throw new Error('Ungültiger Preset-Snapshot (Schema).');
  }
  if (snapshot.ruleset_key !== 'sagatree-core') {
    throw new Error('Presets sind derzeit nur für SagaTree Core verfügbar.');
  }
  if (!snapshot.name.trim()) {
    throw new Error('Preset-Snapshot braucht einen Charakternamen.');
  }
  if (!isGenderReading(snapshot.appearance?.gender_reading)) {
    throw new Error('Preset-Snapshot braucht eine gültige Geschlechts-Lesart.');
  }
  const level = snapshot.level;
  if (!Number.isInteger(level) || level < 1 || level > 20) {
    throw new Error('Preset-Level muss zwischen 1 und 20 liegen.');
  }

  const profile = snapshot.sagatree_profile;
  if (!profile) {
    throw new Error('Preset-Snapshot braucht ein SagaTree-Profil.');
  }
  if (!isSagaTreeEssenceKey(profile.essence)) {
    throw new Error('Preset-Snapshot braucht eine Essenz.');
  }

  const bg = profile.background;
  if (!bg?.name?.trim()) {
    throw new Error('Preset-Snapshot: Hintergrund braucht einen Namen.');
  }
  if (![bg.milieuAccess, bg.contact, bg.complication, bg.communication].every((field) => typeof field === 'string' && field.trim())) {
    throw new Error('Preset-Snapshot: Hintergrund-Felder (Milieu/Kontakt/Komplikation/Kommunikation) unvollständig.');
  }

  const traitKeys = (profile.speciesTraitInstances ?? []).map((instance) => instance.trait);
  if (getSagaTreeSpeciesTraitCost(traitKeys) !== SAGA_TREE_SPECIES_TRAIT_BUDGET) {
    throw new Error(`Preset-Snapshot: Speziesmerkmale müssen genau ${SAGA_TREE_SPECIES_TRAIT_BUDGET} Punkte ergeben.`);
  }
  if (snapshot.race === 'alien' && !profile.speciesProfile?.name?.trim()) {
    throw new Error('Preset-Snapshot: Alien-Speziesprofil braucht einen Namen.');
  }
  if (!profile.baseAttributes) {
    throw new Error('Preset-Snapshot: baseAttributes fehlen.');
  }

  assertValidSagaTreeCharacterPersistence(snapshot.attributes, snapshot.skills, profile, level);
}

function withSafePortraitUrl(snapshot: CharacterPresetSnapshot): CharacterPresetSnapshot {
  if (!snapshot.portrait_url) return snapshot;
  const safePortrait = normalizeSafeUrl(snapshot.portrait_url);
  if (safePortrait === snapshot.portrait_url) return snapshot;
  return { ...snapshot, portrait_url: safePortrait };
}

function normalizeSnapshot(value: unknown): CharacterPresetSnapshot | null {
  if (!isRecord(value) || value.schemaVersion !== 1) return null;
  if (typeof value.name !== 'string' || typeof value.race !== 'string' || typeof value.class !== 'string') return null;
  if (typeof value.level !== 'number') return null;
  const rawRuleset = typeof value.ruleset_key === 'string' && isCharacterRulesetKey(value.ruleset_key)
    ? value.ruleset_key
    : 'sagatree-core';
  const rulesetKey: CharacterRulesetKey = rawRuleset === 'dnd-5.5e' ? 'dnd-5.5e' : 'sagatree-core';
  const appearance = normalizeCharacterAppearance(isRecord(value.appearance) ? value.appearance : undefined);
  const profileRecord = isRecord(value.sagatree_profile) ? value.sagatree_profile : null;
  const profile = profileRecord ? (profileRecord as unknown as SagaTreeProfileDto) : null;
  if (!profile) return null;

  const snapshot: CharacterPresetSnapshot = {
    schemaVersion: 1,
    name: value.name,
    description: typeof value.description === 'string' ? value.description : '',
    class: value.class,
    race: value.race,
    ruleset_key: rulesetKey,
    level: value.level,
    appearance,
    attributes: {
      strength: typeof (value.attributes as CharacterAttributesDto | undefined)?.strength === 'number' ? (value.attributes as CharacterAttributesDto).strength : 0,
      dexterity: typeof (value.attributes as CharacterAttributesDto | undefined)?.dexterity === 'number' ? (value.attributes as CharacterAttributesDto).dexterity : 0,
      endurance: typeof (value.attributes as CharacterAttributesDto | undefined)?.endurance === 'number' ? (value.attributes as CharacterAttributesDto).endurance : 0,
      mind: typeof (value.attributes as CharacterAttributesDto | undefined)?.mind === 'number' ? (value.attributes as CharacterAttributesDto).mind : 0,
      perception: typeof (value.attributes as CharacterAttributesDto | undefined)?.perception === 'number' ? (value.attributes as CharacterAttributesDto).perception : 0,
      charisma: typeof (value.attributes as CharacterAttributesDto | undefined)?.charisma === 'number' ? (value.attributes as CharacterAttributesDto).charisma : 0,
    },
    skills: normalizeSkills(value.skills),
    sagatree_profile: profile,
    abilities: Array.isArray(value.abilities) ? value.abilities as CharacterPresetSnapshot['abilities'] : [],
    inventory: Array.isArray(value.inventory) ? value.inventory as CharacterPresetSnapshot['inventory'] : [],
  };
  if (typeof value.background_story === 'string') snapshot.background_story = value.background_story;
  if (typeof value.notes === 'string') snapshot.notes = value.notes;
  if (Array.isArray(value.personality_traits)) snapshot.personality_traits = value.personality_traits.filter((entry): entry is string => typeof entry === 'string');
  if (Array.isArray(value.ideals)) snapshot.ideals = value.ideals.filter((entry): entry is string => typeof entry === 'string');
  if (Array.isArray(value.bonds)) snapshot.bonds = value.bonds.filter((entry): entry is string => typeof entry === 'string');
  if (Array.isArray(value.flaws)) snapshot.flaws = value.flaws.filter((entry): entry is string => typeof entry === 'string');
  if (typeof value.portrait_url === 'string' && value.portrait_url.trim()) {
    const safePortrait = normalizeSafeUrl(value.portrait_url);
    if (safePortrait) snapshot.portrait_url = safePortrait;
  }
  return snapshot;
}

function normalizeVersions(value: unknown): CharacterPresetVersionDto[] {
  if (!Array.isArray(value)) return [];
  const versions: CharacterPresetVersionDto[] = [];
  for (const item of value) {
    if (!isRecord(item) || typeof item.level !== 'number' || typeof item.created_at !== 'string') continue;
    const snapshot = normalizeSnapshot(item.snapshot);
    if (!snapshot) continue;
    try {
      assertValidSnapshot(snapshot);
    } catch (error) {
      console.error(
        'Skipping invalid preset version on read:',
        error instanceof Error ? error.message : error,
      );
      continue;
    }
    versions.push({ level: item.level, snapshot, created_at: item.created_at });
  }
  return versions.sort((a, b) => a.level - b.level || a.created_at.localeCompare(b.created_at));
}

function mapToViewModel(dto: CharacterPresetDto, sourceMissing: boolean): CharacterPresetVm {
  return {
    id: dto.id,
    displayName: dto.display_name,
    rulesetKey: isCharacterRulesetKey(dto.ruleset_key) ? dto.ruleset_key : 'sagatree-core',
    origin: isPresetOrigin(dto.origin) ? dto.origin : 'user',
    sourceCharacterId: dto.source_character_id,
    sourceCharacterMissing: sourceMissing,
    published: dto.published === true,
    versions: normalizeVersions(dto.versions),
    createdAt: new Date(dto.created_at),
    updatedAt: new Date(dto.updated_at),
  };
}

