  let best: THREE.SkinnedMesh | null = null;
  let bestBoneCount = 0;
  root.traverse((object) => {
    if (!(object instanceof THREE.SkinnedMesh)) return;
    const count = object.skeleton?.bones?.length ?? 0;
    if (count > bestBoneCount) {
      best = object;
      bestBoneCount = count;
    }
  });
  return best;
}

